from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class DistNamesSlot(SchemaObject):
    config = SchemaField(name="config")
    runtime = SchemaField(name="runtime")

    def __init__(self, config, runtime):
        self.config = config
        self.runtime = runtime
        super(DistNamesSlot, self).__init__()


class X2LinkSlot(SchemaObject):
    id = SchemaField(name="id")
    enb_id = SchemaField(name="eNodebId")
    mcc = SchemaField(name="mcc")
    mnc = SchemaField(name="mnc")
    mnc_length = SchemaField(name="mncLength")
    ip_address = SchemaField(name="ipAddress")
    x2_link_status = SchemaField(name="x2LinkStatus")
    x2_link_lock = SchemaField(name="x2LinkLock")
    alarms = SchemaField(name="alarms")
    dist_names = SchemaField(name="distNames", klass=DistNamesSlot)

    def __init__(self, id, enb_id, mcc, mnc, mnc_length, ip_address, x2_link_status, x2_link_lock, alarms, dist_names):
        self.id = id
        self.enb_id = enb_id
        self.mcc = mcc
        self.mnc = mnc
        self.mnc_length = mnc_length
        self.ip_address = ip_address
        self.x2_link_status = x2_link_status
        self.x2_link_lock = x2_link_lock
        self.alarms = alarms
        self.dist_names = dist_names
        super(X2LinkSlot, self).__init__()


class X2LinksDiffResponseASMV1(SchemaObject):
    revision = SchemaField(name="revision", not_null=True)
    created = SchemaField(name="created", not_null=True, klass=X2LinkSlot, many=True)
    updated = SchemaField(name="updated", not_null=True, klass=X2LinkSlot, many=True)
    removed = SchemaField(name="removed", not_null=True)

    def __init__(self, revision, created, updated, removed):
        self.revision = revision
        self.created = created
        self.updated = updated
        self.removed = removed

        super(X2LinksDiffResponseASMV1, self).__init__()
